#!/usr/bin/env python3
"""Compute numeric ground truth for CSX-292_Q2 from local package data."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any


TASK_ID = "CSX-292_Q2"
EVENT_ID = "CSX-292"
SOURCE_FILES = [
    "data/event_reports/event_reports_003_Locked_event_anchor_2022_Pakistan_extreme_monsoon_floods.json",
    "data/physical_hazard/physical_hazard_003_NASA_POWER_daily_point_sample.json",
    "data/physical_hazard/physical_hazard_004_Open-Meteo_archive_point_sample.json",
    "data/physical_hazard/physical_hazard_005_ERA5-Land_hourly_aggregate_stats.json",
    "data/physical_hazard/physical_hazard_007_GPM_IMERG_V07_event_accumulated_precipitation.json",
    "data/physical_hazard/physical_hazard_009_CHIRPS_daily_event_accumulated_precipitation.json",
]


def load_json(package_dir: Path, rel_path: str) -> dict[str, Any]:
    with (package_dir / rel_path).open("r", encoding="utf-8-sig") as handle:
        return json.load(handle)


def mean(values: list[float]) -> float:
    return sum(values) / len(values)


def iso_from_power_date(value: str) -> str:
    return f"{value[:4]}-{value[4:6]}-{value[6:]}"


def round1(value: float) -> float:
    return round(value + 0.0, 1)


def build_rubric() -> dict[str, Any]:
    return {
        "total_points": 20,
        "criteria": [
            {
                "name": "answer_schema",
                "points": 4,
                "description": "Returns the requested compact JSON fields and final computed label.",
            },
            {
                "name": "numeric_anchors",
                "points": 5,
                "description": "Computes peak date, peak precipitation, pulse shares, cooling values, regional precipitation, and wind maxima within 0.1 units.",
            },
            {
                "name": "formula_application",
                "points": 4,
                "description": "Applies the pulse-share, cooling, regional-mean, regional-spread, and wind-ceiling formulas to the stated windows.",
            },
            {
                "name": "threshold_ledger",
                "points": 4,
                "description": "Evaluates all threshold comparisons and identifies that every component test passes.",
            },
            {
                "name": "computed_label",
                "points": 2,
                "description": "Derives wet_cooling_monsoon_pulse from the pass state and rejects wind-led or heat-led labels through numeric thresholds.",
            },
            {
                "name": "scope_control",
                "points": 1,
                "description": "Keeps the conclusion within the package-derived calculation.",
            },
        ],
    }


def build_computed() -> dict[str, Any]:
    task_dir = Path(__file__).resolve().parent
    repo_root = task_dir.parents[2]
    package_dir = repo_root / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID

    anchor = load_json(package_dir, SOURCE_FILES[0])
    power = load_json(package_dir, SOURCE_FILES[1])
    open_meteo = load_json(package_dir, SOURCE_FILES[2])
    era5 = load_json(package_dir, SOURCE_FILES[3])
    gpm = load_json(package_dir, SOURCE_FILES[4])
    chirps = load_json(package_dir, SOURCE_FILES[5])

    power_params = power["properties"]["parameter"]
    power_precip = {date: float(value) for date, value in power_params["PRECTOTCORR"].items()}
    power_temp = {date: float(value) for date, value in power_params["T2M"].items()}
    power_wind = {date: float(value) for date, value in power_params["WS10M"].items()}

    daily = open_meteo["daily"]
    om_dates = daily["time"]
    om_precip = dict(zip(om_dates, map(float, daily["precipitation_sum"])))
    om_temp = dict(zip(om_dates, map(float, daily["temperature_2m_max"])))
    om_wind = dict(zip(om_dates, map(float, daily["wind_speed_10m_max"])))

    power_peak_raw = max(power_precip, key=lambda date: (power_precip[date], date))
    power_peak_day = iso_from_power_date(power_peak_raw)
    om_peak_day = max(om_precip, key=lambda date: (om_precip[date], date))

    power_total = sum(power_precip.values())
    om_total = sum(om_precip.values())
    power_pulse_total = sum(power_precip[date] for date in ["20220620", "20220621", "20220622"])
    om_pulse_total = sum(om_precip[date] for date in ["2022-06-20", "2022-06-21", "2022-06-22"])

    power_baseline_temp = mean([power_temp["20220615"], power_temp["20220616"]])
    om_baseline_temp = mean([om_temp["2022-06-15"], om_temp["2022-06-16"]])

    regional_precip = [
        float(era5["stats"]["precipitation_sum_mm_mean"]),
        float(gpm["stats"]["gpm_event_precip_mm_mean"]),
        float(chirps["stats"]["chirps_event_precip_mm_mean"]),
    ]
    regional_mean = mean(regional_precip)
    regional_spread_pct = (max(regional_precip) - min(regional_precip)) / regional_mean * 100.0

    metrics = {
        "peak_day": power_peak_day,
        "peak_precip_mm": {
            "nasa_power": round1(power_precip[power_peak_raw]),
            "open_meteo": round1(om_precip[om_peak_day]),
        },
        "pulse_share_pct": {
            "nasa_power": round1(power_pulse_total / power_total * 100.0),
            "open_meteo": round1(om_pulse_total / om_total * 100.0),
        },
        "cooling_c": {
            "nasa_power": round1(power_baseline_temp - power_temp[power_peak_raw]),
            "open_meteo": round1(om_baseline_temp - om_temp[om_peak_day]),
        },
        "regional": {
            "mean_mm": round1(regional_mean),
            "spread_pct": round1(regional_spread_pct),
        },
        "wind": {
            "nasa_power_max_ms": round1(max(power_wind.values())),
            "open_meteo_max_kmh": round1(max(om_wind.values())),
        },
    }

    tests = {
        "same_peak_day": power_peak_day == om_peak_day,
        "pulse_share_ge_50_pct": all(value >= 50.0 for value in metrics["pulse_share_pct"].values()),
        "cooling_ge_5_c": all(value >= 5.0 for value in metrics["cooling_c"].values()),
        "regional_mean_ge_200_mm": metrics["regional"]["mean_mm"] >= 200.0,
        "regional_spread_le_15_pct": metrics["regional"]["spread_pct"] <= 15.0,
        "wind_below_ceiling": (
            metrics["wind"]["nasa_power_max_ms"] < 10.0
            and metrics["wind"]["open_meteo_max_kmh"] < 40.0
        ),
    }
    all_tests_pass = all(tests.values())
    label = "wet_cooling_monsoon_pulse" if all_tests_pass else "threshold_mismatch"

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "numeric",
            "evaluation_mode": "deterministic",
            "difficulty_level": "L3",
            "target_family": "pakistan_monsoon_wet_cooling_pulse_ledger",
        "primary_gt": {
            "answer": label,
            "peak_day": metrics["peak_day"],
            "peak_precip_mm": metrics["peak_precip_mm"],
            "pulse_share_pct": metrics["pulse_share_pct"],
            "cooling_c": metrics["cooling_c"],
            "regional": metrics["regional"],
            "wind": metrics["wind"],
            "all_tests_pass": all_tests_pass,
        },
        "event": {
            "package_id": EVENT_ID,
            "event_name": anchor["event_name"],
            "hazard_family": anchor["hazard_family"],
            "analysis_window": "2022-06-15 to 2022-06-29 daily point series; regional accumulation through 2022-07-30",
            "window_semantics": "Point-series pulse, cooling, and wind tests use the 2022-06-15 to 2022-06-29 daily records; regional precipitation uses the package-supplied accumulated regional summaries.",
        },
        "formulas": {
            "peak_day": "date of maximum daily precipitation in each point series",
            "pulse_share_pct": "100 * sum(precipitation from 2022-06-20 through 2022-06-22) / sum(precipitation over 2022-06-15 through 2022-06-29)",
            "cooling_c": "mean of each point series' available daily temperature field on 2022-06-15 and 2022-06-16 minus that same series' temperature on the peak-rain day",
            "regional_mean_mm": "mean of ERA5-Land, GPM IMERG, and CHIRPS regional accumulated precipitation means",
            "regional_spread_pct": "100 * (maximum regional mean - minimum regional mean) / regional_mean_mm",
            "wind_ceiling": "NASA POWER maximum wind < 10 m/s and Open-Meteo maximum wind < 40 km/h",
        },
        "thresholds": {
            "same_peak_day": True,
            "minimum_pulse_share_pct_each_series": 50.0,
            "minimum_cooling_c_each_series": 5.0,
            "minimum_regional_mean_mm": 200.0,
            "maximum_regional_spread_pct": 15.0,
            "wind_ceiling_required": True,
        },
        "component_tests": tests,
        "rubric": build_rubric(),
        "tolerances": {
            "precip_mm": 0.1,
            "percent": 0.1,
            "temperature_c": 0.1,
            "wind": 0.1,
            "regional_mean_mm": 0.1,
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
        },
    }


def main() -> None:
    task_dir = Path(__file__).resolve().parent
    output_path = task_dir / "computed_gt.json"
    output_path.write_text(json.dumps(build_computed(), indent=2, sort_keys=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
